#!/usr/bin/env python3
"""Generate distribution notices from the locked Cargo graph, including fonts."""
import json
from pathlib import Path
import subprocess

root = Path(__file__).resolve().parent.parent
metadata = json.loads(subprocess.check_output(
    ["cargo", "metadata", "--locked", "--format-version", "1"], cwd=root, text=True
))
sections = ["Third-party notices for Linux Task Manager\n"
            "Generated by scripts/licenses.py from the locked Cargo dependency graph.\n"
            "Includes platform-specific dependencies not linked on Linux.\n"
            "System libraries/tools are supplied separately by the distribution.\n"]
for package in sorted(metadata["packages"], key=lambda p: (p["name"], p["version"])):
    if package["name"] == "linux-task-manager":
        continue
    directory = Path(package["manifest_path"]).parent
    sections.append(f"\n{'=' * 72}\n{package['name']} {package['version']}\n"
                    f"License: {package.get('license') or 'See bundled license'}\n"
                    f"Source: https://crates.io/crates/{package['name']}/{package['version']}\n")
    files = set()
    for pattern in ("LICENSE*", "LICENCE*", "COPYING*", "NOTICE*", "license*", "licence*"):
        files.update(p for p in directory.glob(pattern) if p.is_file())
    if package.get("license_file"):
        files.add(directory / package["license_file"])
    # epaint embeds these fonts into the executable; their notices are below root.
    if package["name"] == "epaint_default_fonts":
        files.update(directory.glob("fonts/*.txt"))
    for path in sorted(files):
        if path.is_file():
            sections.append(f"\n--- {path.relative_to(directory)} ---\n{path.read_text(errors='replace')}\n")
(root / "THIRD-PARTY-LICENSES.txt").write_text(
    "\n".join(line.rstrip() for line in "".join(sections).splitlines()).rstrip() + "\n"
)
